// tests/secrets.test.ts
import { describe, it, expect } from 'vitest';
import { SECRETS_VERSION, maskSecret } from '../src/secrets.js';

describe('secrets 模块', () => {
  it('模块版本号存在', () => {
    expect(SECRETS_VERSION).toBe(1);
  });
});

describe('maskSecret', () => {
  it('默认隐藏除最后 4 位以外的所有字符', () => {
    expect(maskSecret('abcdefgh')).toBe('****efgh');
    expect(maskSecret('sk-12345678')).toBe('********5678');
  });

  it('长度刚好等于 visibleEnd + 2 时开始打码', () => {
    // 'abcdef' 长度为 6，默认 visibleEnd=4，6 === 4 + 2，应打码
    expect(maskSecret('abcdef')).toBe('**cdef');
  });

  it('短于 visibleEnd + 2 时原样返回', () => {
    expect(maskSecret('a')).toBe('a');
    expect(maskSecret('abcde')).toBe('abcde');
    expect(maskSecret('')).toBe('');
  });

  it('支持自定义 visibleEnd 参数', () => {
    expect(maskSecret('abcdef', 1)).toBe('**c');
    // 'abcd' 长度 4，visibleEnd=1，4 >= 1 + 2，应打码
    expect(maskSecret('abcd', 1)).toBe('***d');
    // 'ab' 长度 2，visibleEnd=1，2 < 1 + 2，原样返回
    expect(maskSecret('ab', 1)).toBe('ab');
    expect(maskSecret('abcdef', 2)).toBe('****ef');
  });
});

// src/secrets.ts
// 密钥工具
export const SECRETS_VERSION = 1;

/**
 * 将密钥打码：除最后 visibleEnd 位之外，其余字符全部替换为星号。
 * 当 value 长度短于 visibleEnd + 2 时，原样返回。
 */
export function maskSecret(value: string, visibleEnd = 4): string {
  if (value.length < visibleEnd + 2) {
    return value;
  }
  const maskedLength = value.length - visibleEnd;
  return '*'.repeat(maskedLength) + value.slice(-visibleEnd);
}

